        /**
         * @description Single-row tenant configuration editable by the tenant administrator.
         *
         *     One row is created per tenant DB during onboarding. Access is via the
         *     singleton endpoints GET /api/tenant/settings and PATCH /api/tenant/settings
         *     — there is no collection endpoint and no row ID in the URL.
         */
        "TenantSettings-tenant_settings.read": {
            /**
             * @description SUNAT tax regime. NRUS tenants can issue exonerated boletas, but not facturas.
             * @default GENERAL
             * @enum {string}
             */
            taxRegime: "GENERAL" | "NRUS";
            /** @default 18 */
            igv: number;
            /** @default 0 */
            rc: number;
            /** @default true */
            printLogo: boolean;
            /** @default true */
            requireCashRegister: boolean;
            /**
             * @default WEBUSB
             * @enum {string}
             */
            printMethod: "WEBUSB" | "LOCAL_AGENT";
            /** @default true */
            autoInvoice: boolean;
            /**
             * @description When true, the POS sends the sale ticket to the printer automatically
             *     after every checkout. When false, the operator prints on demand from the
             *     "última venta" panel.
             * @default true
             */
            autoPrint: boolean;
            /**
             * @description Apply Peru's customer-favourable S/ 0.10 rounding to cash-only POS sales.
             * @default false
             */
            cashRoundingEnabled: boolean;
            /**
             * @description Show a piece counter on weighted POS lines (sold by kg) that prefixes the
             *     line description with the number of units, e.g. "2 Pechuga de pollo".
             * @default false
             */
            posPieceCountEnabled: boolean;
            /**
             * @default PEN
             * @enum {string}
             */
            defaultCurrency: "PEN" | "USD";
            /**
             * @description Default number of days between a recurring charge being generated and
             *     its due date, used when a SubscriptionPlan does not override it.
             * @default 15
             */
            defaultPaymentTermDays: number;
            /**
             * @default STRICT
             * @enum {string}
             */
            negativeStockPolicy: "STRICT" | "WARNING_ONLY" | "ALLOW_NEGATIVE";
            /**
             * @description Vertical (business type) key selected during onboarding, e.g. "retail" or
             *     "pharmacy". Written by the VerticalPreset applier, not by tenant PATCH.
             * @default retail
             */
            vertical: string;
            /**
             * @description Marks that the post-provisioning tenant onboarding wizard has been
             *     completed. Used by the React OnboardingGate to decide whether to show
             *     setup or the normal shell.
             * @default false
             */
            onboardingCompleted: boolean;
        };
